import{_ as e,o as a,c as t,Q as o}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"IFC Parsing Setup (IFC PS)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/ifcps/index.md","filePath":"guide/management/ifcps/index.md","lastUpdated":1790250076000}'),r={name:"guide/management/ifcps/index.md"},s=o('<h1 id="ifc-parsing-setup-ifc-ps" tabindex="-1">IFC Parsing Setup (IFC PS) <a class="header-anchor" href="#ifc-parsing-setup-ifc-ps" aria-label="Permalink to &quot;IFC Parsing Setup (IFC PS)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Why this exists</p><p>The IFC standard is open and versatile, and every BIM application exports it in its own way. What one exporter calls <code>REFERENCE</code> another writes as a property set value, and a stud can be recognised by its name in one file and by its profile in the next. An IFC Parsing Setup is how you tell produuz.it to read <strong>your</strong> files.</p></div><p>A company can have several setups, and <strong>each project uses one</strong>. Open them in <strong>Company settings → IFC Parsing Setups</strong>.</p><p>Every setting has an <strong>(i)</strong> button that opens the help panel on the right, with the same explanation you find here plus a typical example. The panel follows whatever you pressed last, so you can leave it open while you work.</p><div class="tip custom-block"><p class="custom-block-title">Let Claude write it for you</p><p>Building a setup from scratch is the slowest part of onboarding, and it is what the <strong>Claude connector</strong> is most useful for. Give Claude the property list of a few elements from your BIM application, describe your panels in your own words, and ask it for the setup. It writes a JSON file you upload with the <strong>UPLOAD</strong> button, and you check it tab by tab before saving.</p><p>See: <a href="/guide/management/ifcps/json/">The setup file (JSON)</a> · <a href="/guide/mcp/">Claude connector (MCP)</a></p></div><h2 id="how-a-setup-is-organised" tabindex="-1">How a setup is organised <a class="header-anchor" href="#how-a-setup-is-organised" aria-label="Permalink to &quot;How a setup is organised&quot;">​</a></h2><p>The editor has seven tabs, in this order:</p><table><thead><tr><th>Tab</th><th>What you set there</th></tr></thead><tbody><tr><td><a href="#hierarchy-and-project">Hierarchy and project</a></td><td>How the file is split into modules and panels, where the names, phases and batches come from, and which assemblies are produced at all</td></tr><tr><td><a href="#custom-part-branches">Custom part branches</a></td><td>Your own kinds of part beyond the built-in ones</td></tr><tr><td><a href="#panel-part-categories">Panel part categories</a></td><td>Which elements are rails, studs, plates, bricks, openings and areas</td></tr><tr><td><a href="#steel-cage-part-categories">Steel cage part categories</a></td><td>The same, for the steel cage flow</td></tr><tr><td><a href="#part-properties">Part properties</a></td><td>Where each value of a part is read from</td></tr><tr><td><a href="#custom-part-classes">Custom part classes</a></td><td>Kinds of part you tell apart inside a category, and what they do to the panel measurements</td></tr><tr><td><a href="#operations-and-machines">Operations and machines</a></td><td>Which elements are nail lines, cuts and drills, and what the machine files read</td></tr></tbody></table><p>The filter box at the top left of each tab searches the settings by name, and also by the values inside their rules, so typing <code>STIJL</code> lands on every rule that uses it.</p><h2 id="the-two-kinds-of-entry" tabindex="-1">The two kinds of entry <a class="header-anchor" href="#the-two-kinds-of-entry" aria-label="Permalink to &quot;The two kinds of entry&quot;">​</a></h2><p>Almost everything in a setup is one of two things.</p><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><p>Used by categories, by the assembly filter and by the machine flags. Each rule has three fields:</p><ul><li><strong>IFC Prop</strong> — the property to look into.</li><li><strong>Type of match</strong> — <em>Match full word</em>, <em>Match prefix</em> or <em>Contains word</em>.</li><li><strong>Value</strong> — what to look for.</li></ul><p>A part matches the setting when <strong>any one</strong> of its rules matches.</p><div class="tip custom-block"><p class="custom-block-title">Example</p><p>Two rules on the <em>Top Rail Wood</em> category:</p><table><thead><tr><th>IFC Prop</th><th>Type of match</th><th>Value</th></tr></thead><tbody><tr><td>REFERENCE</td><td>Match full word</td><td>TOPRAIL</td></tr><tr><td>REFERENCE</td><td>Match prefix</td><td>TR</td></tr></tbody></table><p>Parts with a <code>REFERENCE</code> of <strong>TOPRAIL</strong>, <strong>TR</strong>, <strong>TR12</strong> or <strong>TR45</strong> are top rails. <code>TOPRAIL2</code>, <code>TOP_RAIL</code> and <code>12TR</code> are not.</p></div><h3 id="property-names" tabindex="-1">Property names <a class="header-anchor" href="#property-names" aria-label="Permalink to &quot;Property names&quot;">​</a></h3><p>Used by the properties. Here you only list the <strong>IFC property names</strong> that may hold the value, in order of preference. The first one present on the element wins.</p><div class="tip custom-block"><p class="custom-block-title">Example</p><p>Two names on the <em>Zone (layer)</em> property, <code>WorkPlane</code> and <code>Layer</code>:</p><table><thead><tr><th>Part</th><th><code>WorkPlane</code></th><th><code>Layer</code></th><th>Detected zone</th></tr></thead><tbody><tr><td>P1</td><td>1</td><td>2</td><td>1</td></tr><tr><td>P2</td><td><em>(absent)</em></td><td>3</td><td>3</td></tr><tr><td>P3</td><td>1</td><td><em>(absent)</em></td><td>1</td></tr></tbody></table></div><div class="warning custom-block"><p class="custom-block-title">Case does not matter</p><p>Property names and values are matched <strong>case-insensitively</strong>. <code>Reference</code>, <code>REFERENCE</code> and <code>reference</code> are the same thing.</p></div><h3 id="reading-from-a-specific-property-set" tabindex="-1">Reading from a specific property set <a class="header-anchor" href="#reading-from-a-specific-property-set" aria-label="Permalink to &quot;Reading from a specific property set&quot;">​</a></h3><p>By default produuz.it looks for a property <strong>anywhere in the element</strong>: in any of its property sets, and among the element&#39;s own attributes. That is what you want almost always.</p><p>It becomes a problem when the same property name exists in two property sets with different values — the exporter&#39;s <code>REFERENCE</code> and your own <code>REFERENCE</code>, say. Then it is luck which one is read.</p><p>Every rule and every property name has a <strong>Read from a specific property set</strong> checkbox for that case:</p><table><thead><tr><th>Checkbox</th><th>Field</th><th>What is read</th></tr></thead><tbody><tr><td>unticked</td><td>—</td><td>The property wherever it appears. The normal case.</td></tr><tr><td>ticked</td><td><code>Tekla_Common</code></td><td>That property set only. Another set carrying a property of the same name is ignored.</td></tr><tr><td>ticked</td><td><em>(left empty)</em></td><td>The element&#39;s own attributes only: <code>name</code>, <code>ifc_tag</code>, <code>ifc_id</code>, <code>object_type</code>, <code>description</code>.</td></tr></tbody></table><p>Tick it when you have a reason to. An unticked entry behaves exactly as it always has, and setups saved before this existed are untouched.</p><h2 id="hierarchy-and-project" tabindex="-1">Hierarchy and project <a class="header-anchor" href="#hierarchy-and-project" aria-label="Permalink to &quot;Hierarchy and project&quot;">​</a></h2><p>How the file is split, what the pieces are called, and which of them you actually produce.</p><h3 id="levels-detection" tabindex="-1">Levels detection <a class="header-anchor" href="#levels-detection" aria-label="Permalink to &quot;Levels detection {#levels-detection}&quot;">​</a></h3><p>Says how elements are grouped into modules, assemblies and subassemblies: either by an <strong>IFC class</strong> (usually <code>IfcElementAssembly</code>) or by the value of a <strong>property</strong>, for exporters that write no containers at all.</p><h3 id="unit-and-project-properties" tabindex="-1">Unit and project properties <a class="header-anchor" href="#unit-and-project-properties" aria-label="Permalink to &quot;Unit and project properties {#unit-and-project-properties}&quot;">​</a></h3><p><em>Levels detection</em> above says how a module and an assembly are recognised. These say what is read from each one once it has been: what it is called, which phase and batch it belongs to, and any extra values of yours that should travel with it.</p><p>They are read off the <strong>container</strong> — the module or the assembly — and not off its parts. Everything read off a part is in the <a href="#part-properties">Part properties</a> tab.</p><p>Leave one empty and produuz.it falls back to its own default, which for a name is the container element&#39;s own name.</p><h4 id="module-name" tabindex="-1">Module name <a class="header-anchor" href="#module-name" aria-label="Permalink to &quot;Module name {#module-name}&quot;">​</a></h4><p>The properties holding the module design name, for example <code>Modulenummer</code>. Instances of the same design share this value.</p><h4 id="module-unit-id" tabindex="-1">Module unit ID <a class="header-anchor" href="#module-unit-id" aria-label="Permalink to &quot;Module unit ID {#module-unit-id}&quot;">​</a></h4><p>The properties holding the unique id of each module instance. Without it, modules sharing a name are merged into one and you get a warning.</p><h4 id="assembly-name" tabindex="-1">Assembly name <a class="header-anchor" href="#assembly-name" aria-label="Permalink to &quot;Assembly name {#assembly-name}&quot;">​</a></h4><p>The properties holding the panel name. Left empty, the container&#39;s own name is used.</p><h4 id="phase-name" tabindex="-1">Phase Name <a class="header-anchor" href="#phase-name" aria-label="Permalink to &quot;Phase Name {#phase-name}&quot;">​</a></h4><p>The property holding the phase a panel belongs to. Phases and batches are created from these values when the file is split.</p><h4 id="batch-name" tabindex="-1">Batch Name <a class="header-anchor" href="#batch-name" aria-label="Permalink to &quot;Batch Name {#batch-name}&quot;">​</a></h4><p>The property holding the batch a panel belongs to.</p><h4 id="auto-parsed-client-meta" tabindex="-1">Auto Parsed Client Meta <a class="header-anchor" href="#auto-parsed-client-meta" aria-label="Permalink to &quot;Auto Parsed Client Meta {#auto-parsed-client-meta}&quot;">​</a></h4><p>Properties copied onto the design as client data when the file is analysed. Useful for anything of yours that has no field of its own.</p><h3 id="assembly-filter" tabindex="-1">Assembly filter <a class="header-anchor" href="#assembly-filter" aria-label="Permalink to &quot;Assembly filter&quot;">​</a></h3><p>A project file usually holds more than you produce: foundations, in-situ concrete, the building next door. Two lists decide what the splitter takes out of it.</p><h4 id="split-only-these-assemblies" tabindex="-1">Split only these assemblies <a class="header-anchor" href="#split-only-these-assemblies" aria-label="Permalink to &quot;Split only these assemblies {#split-only-these-assemblies}&quot;">​</a></h4><p>Leave it empty and <strong>every</strong> assembly is split. With rules in it, only the assemblies matching one of them are split out.</p><h4 id="never-split-these-assemblies" tabindex="-1">Never split these assemblies <a class="header-anchor" href="#never-split-these-assemblies" aria-label="Permalink to &quot;Never split these assemblies {#never-split-these-assemblies}&quot;">​</a></h4><p>Assemblies matching one of these are never split out, <strong>even when the first list keeps them</strong>. The drop list always wins, which is how you keep a whole prefix and still leave a few names out of it.</p><p>An assembly that is not split leaves nothing behind: no IFC file, no design, and nothing in the phase and batch counts.</p><details class="details custom-block"><summary>Example</summary><p><em>Split only these assemblies:</em> <code>ASSEMBLY_PREFIX</code> starts with <code>WA</code></p><p><em>Never split these assemblies:</em> <code>name</code> contains <code>_TEST</code></p><p>You get every wall except the ones whose name carries <code>_TEST</code>. Roofs, floors and everything else in the file are left alone.</p></details><h2 id="custom-part-branches" tabindex="-1">Custom part branches <a class="header-anchor" href="#custom-part-branches" aria-label="Permalink to &quot;Custom part branches {#custom-part-branches}&quot;">​</a></h2><p>Branches are kinds of part beyond the built-in timber and plate: windows, connectors, airtightness, electrical, plumbing.</p><p>Each branch has a name, its own rules, the geometry it <strong>resembles</strong> — wood-like, plate-like or generic, so drawings, counts and cutting lists know how to treat it — and two switches.</p><h3 id="branch-logistics" tabindex="-1">Logistics enabled <a class="header-anchor" href="#branch-logistics" aria-label="Permalink to &quot;Logistics enabled {#branch-logistics}&quot;">​</a></h3><p>The parts of this branch reach the <strong>parts list</strong> and go through logistics.</p><h3 id="branch-in-metrics" tabindex="-1">Counts in the panel measurements <a class="header-anchor" href="#branch-in-metrics" aria-label="Permalink to &quot;Counts in the panel measurements {#branch-in-metrics}&quot;">​</a></h3><p>The parts of this branch take part in the panel <strong>width, height, thickness and surface</strong>.</p><p>This exists because a branch is recognised <em>before</em> a part falls back to timber, plate or steel from its category. A part your setup recognises perfectly well as a window frame or a cladding profile can therefore have no category at all, and a part with no category is outside every measurement — which is why a panel can read thinner or smaller than it is, with no warning.</p><p>Leave it <strong>off</strong> for brackets, connectors and anything that sticks out past the frame: counting those makes the panel read wider and taller than it is. Turn it <strong>on</strong> for cladding, window frames and layers that are really part of the panel.</p><div class="info custom-block"><p class="custom-block-title">The measurements are not only a report figure</p><p>The <strong>rack loads</strong> are drawn from them. The width decides how many panels fit in a rack row and the thickness how deep the stack builds, so a panel measured short is a rack plan that does not fit on the floor. See: <a href="/guide/logistics/delivery/">Delivery &amp; Racks</a></p></div><div class="info custom-block"><p class="custom-block-title">It only decides whether the part takes part at all</p><p>Which measurements it is then left out of is a <strong>custom part class</strong> job. A window frame that should set the thickness but add no surface gets the switch here <em>and</em> a class with <em>Ignore in surface</em>. The branch says whether the part participates; the class says what it is out of. See: <a href="#custom-part-classes">Custom part classes</a></p></div><div class="info custom-block"><p class="custom-block-title">Both switches are off by default</p><p>Turning this on changes the measurements of every panel holding parts of that branch, from its next analysis. Nothing moves until you tick it.</p></div><h2 id="panel-part-categories" tabindex="-1">Panel part categories <a class="header-anchor" href="#panel-part-categories" aria-label="Permalink to &quot;Panel part categories&quot;">​</a></h2><p>The elements that make up a prefabricated panel. Every rule here matches the <strong>raw IFC properties</strong> of the element — its Name, Reference, Material and the rest, exactly as the modeller exported them.</p><h3 id="frame" tabindex="-1">Frame <a class="header-anchor" href="#frame" aria-label="Permalink to &quot;Frame&quot;">​</a></h3><h4 id="top-rail-wood" tabindex="-1">Top Rail Wood <a class="header-anchor" href="#top-rail-wood" aria-label="Permalink to &quot;Top Rail Wood {#top-rail-wood}&quot;">​</a></h4><p>The horizontal wood at the top of the frame. The studs are nailed into it from above and the panel height is measured from its outer face.</p><h4 id="bottom-rail-wood" tabindex="-1">Bottom Rail Wood <a class="header-anchor" href="#bottom-rail-wood" aria-label="Permalink to &quot;Bottom Rail Wood {#bottom-rail-wood}&quot;">​</a></h4><p>The horizontal wood at the bottom of the frame. The panel&#39;s zero height is its outer face.</p><h4 id="extra-top-wood" tabindex="-1">Extra Top Wood <a class="header-anchor" href="#extra-top-wood" aria-label="Permalink to &quot;Extra Top Wood {#extra-top-wood}&quot;">​</a></h4><p>Woods over the top rail, usually fitted after the studs are nailed.</p><h4 id="extra-bottom-wood" tabindex="-1">Extra Bottom Wood <a class="header-anchor" href="#extra-bottom-wood" aria-label="Permalink to &quot;Extra Bottom Wood {#extra-bottom-wood}&quot;">​</a></h4><p>Woods below the bottom rail, usually fitted after the studs are nailed.</p><h4 id="wood-profile" tabindex="-1">Wood profile <a class="header-anchor" href="#wood-profile" aria-label="Permalink to &quot;Wood profile {#wood-profile}&quot;">​</a></h4><p>Any wood of the frame that is not a rail, a batten or an extra piece: the studs, noggins and diagonals. This is the category the framing nail matrix applies to.</p><h4 id="extra-frame-wood-profile" tabindex="-1">Extra Frame Wood profile <a class="header-anchor" href="#extra-frame-wood-profile" aria-label="Permalink to &quot;Extra Frame Wood profile {#extra-frame-wood-profile}&quot;">​</a></h4><p>Additional frame woods that are not part of the standard framing.</p><h4 id="wood-batten" tabindex="-1">Wood Batten <a class="header-anchor" href="#wood-batten" aria-label="Permalink to &quot;Wood Batten {#wood-batten}&quot;">​</a></h4><p>Battens fixed on the panel.</p><h3 id="plates" tabindex="-1">Plates <a class="header-anchor" href="#plates" aria-label="Permalink to &quot;Plates&quot;">​</a></h3><h4 id="plate" tabindex="-1">Plate <a class="header-anchor" href="#plate" aria-label="Permalink to &quot;Plate {#plate}&quot;">​</a></h4><p>A sheet fixed on a face of the frame: OSB, plasterboard, fibreboard. Its layer decides the zone it is machined in.</p><h4 id="core-plate" tabindex="-1">Core Plate <a class="header-anchor" href="#core-plate" aria-label="Permalink to &quot;Core Plate {#core-plate}&quot;">​</a></h4><p>A plate inside the frame rather than on a face, such as a shear panel.</p><h3 id="other-parts" tabindex="-1">Other parts <a class="header-anchor" href="#other-parts" aria-label="Permalink to &quot;Other parts&quot;">​</a></h3><h4 id="bricks-stones" tabindex="-1">Bricks / Stones <a class="header-anchor" href="#bricks-stones" aria-label="Permalink to &quot;Bricks / Stones {#bricks-stones}&quot;">​</a></h4><p>Single bricks or stones.</p><h4 id="opening" tabindex="-1">Opening <a class="header-anchor" href="#opening" aria-label="Permalink to &quot;Opening {#opening}&quot;">​</a></h4><p>Placeholders for doors and windows. They are not produced; they tell the machines where the frame has a hole and give the reports their opening list.</p><h3 id="areas-and-flags" tabindex="-1">Areas and flags <a class="header-anchor" href="#areas-and-flags" aria-label="Permalink to &quot;Areas and flags&quot;">​</a></h3><p>Elements that are not produced but change how a panel is handled.</p><h4 id="lockout-area" tabindex="-1">Lockout Area <a class="header-anchor" href="#lockout-area" aria-label="Permalink to &quot;Lockout Area {#lockout-area}&quot;">​</a></h4><p>Areas the machine must not work on.</p><h4 id="isolated-area" tabindex="-1">Isolated Area <a class="header-anchor" href="#isolated-area" aria-label="Permalink to &quot;Isolated Area {#isolated-area}&quot;">​</a></h4><p>Areas that carry insulation.</p><h4 id="skip-framing-wood" tabindex="-1">Skip Framing Wood <a class="header-anchor" href="#skip-framing-wood" aria-label="Permalink to &quot;Skip Framing Wood {#skip-framing-wood}&quot;">​</a></h4><p>Parts that would fall into the frame by geometry but must not be counted as framing wood.</p><div class="info custom-block"><p class="custom-block-title">Hiding and ignoring a part are on the classes now</p><p><em>Hidden Material</em> and <em>Ignored Part</em> used to be categories here. They never said what a part <strong>is</strong>, they said how to treat it, so they are <a href="#class-behaviours">class behaviours</a> — <em>Ignore this part completely</em> and <em>Hide in the 3D viewer</em>. Setups that had the old categories were moved across and behave exactly as they did.</p><p><em>Not Isolated Area</em> is gone too. Nothing ever read it.</p></div><h2 id="steel-cage-part-categories" tabindex="-1">Steel cage part categories <a class="header-anchor" href="#steel-cage-part-categories" aria-label="Permalink to &quot;Steel cage part categories&quot;">​</a></h2><p>A secondary flow. Leave it empty if you do not produce steel cages.</p><h4 id="top-steel-profile" tabindex="-1">Top Steel Profile <a class="header-anchor" href="#top-steel-profile" aria-label="Permalink to &quot;Top Steel Profile {#top-steel-profile}&quot;">​</a></h4><h4 id="bottom-steel-profile" tabindex="-1">Bottom Steel Profile <a class="header-anchor" href="#bottom-steel-profile" aria-label="Permalink to &quot;Bottom Steel Profile {#bottom-steel-profile}&quot;">​</a></h4><h4 id="steel-profile" tabindex="-1">Steel Profile <a class="header-anchor" href="#steel-profile" aria-label="Permalink to &quot;Steel Profile {#steel-profile}&quot;">​</a></h4><h4 id="steel-plate" tabindex="-1">Steel Plate <a class="header-anchor" href="#steel-plate" aria-label="Permalink to &quot;Steel Plate {#steel-plate}&quot;">​</a></h4><h4 id="welding-seam" tabindex="-1">Welding Seam <a class="header-anchor" href="#welding-seam" aria-label="Permalink to &quot;Welding Seam {#welding-seam}&quot;">​</a></h4><h4 id="compute-holes" tabindex="-1">Compute holes <a class="header-anchor" href="#compute-holes" aria-label="Permalink to &quot;Compute holes {#compute-holes}&quot;">​</a></h4><p>Whether the holes of the profile are computed for the machine file.</p><h4 id="assembly-id-level1" tabindex="-1">Assembly ID Level1 <a class="header-anchor" href="#assembly-id-level1" aria-label="Permalink to &quot;Assembly ID Level1 {#assembly-id-level1}&quot;">​</a></h4><h4 id="assembly-id-level2" tabindex="-1">Assembly ID Level2 <a class="header-anchor" href="#assembly-id-level2" aria-label="Permalink to &quot;Assembly ID Level2 {#assembly-id-level2}&quot;">​</a></h4><p>The two levels of assembly id of a steel cage.</p><h2 id="part-properties" tabindex="-1">Part properties <a class="header-anchor" href="#part-properties" aria-label="Permalink to &quot;Part properties {#part-properties}&quot;">​</a></h2><p>Where produuz.it reads each value of a part from. Each entry is a list of IFC property names, tried in order.</p><h3 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h3><h4 id="part-name" tabindex="-1">Part Name <a class="header-anchor" href="#part-name" aria-label="Permalink to &quot;Part Name {#part-name}&quot;">​</a></h4><p>The name produuz.it uses for the part, shown in the parts list, the reports and the machine file templates.</p><p>Leave it empty and the part keeps the name the IFC element itself carries. Fill it in when the useful name lives in a property set instead, for example <code>ELEMENT_NAME</code> or <code>Beschrijving</code>.</p><ul><li><strong>The IFC name is always kept.</strong> It stays visible in the part drawer, in the <em>Unknown parts</em> dialog of the viewer, and as its own optional column in the parts list.</li><li><strong>It does not change how parts are classified.</strong> The category and branch rules always match against the raw IFC properties. To match on the property you mapped here, add a rule on that property&#39;s own key.</li></ul><h4 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference {#reference}&quot;">​</a></h4><p>An id expected to be the same across parts of the same shape. Usually <code>reference</code> in Tekla Structures, and available in other exporters too.</p><h4 id="material-name" tabindex="-1">Material Name <a class="header-anchor" href="#material-name" aria-label="Permalink to &quot;Material Name {#material-name}&quot;">​</a></h4><p>The material of the part.</p><h4 id="profile-name" tabindex="-1">Profile Name <a class="header-anchor" href="#profile-name" aria-label="Permalink to &quot;Profile Name {#profile-name}&quot;">​</a></h4><p>The name of the shaped section, for profiles that are not rectangular.</p><h4 id="profile-joined" tabindex="-1">Profile Joined <a class="header-anchor" href="#profile-joined" aria-label="Permalink to &quot;Profile Joined {#profile-joined}&quot;">​</a></h4><p>Whether the profile is extended or joined to another one.</p><h3 id="zone-layer" tabindex="-1">Zone (layer) <a class="header-anchor" href="#zone-layer" aria-label="Permalink to &quot;Zone (layer) {#zone-layer}&quot;">​</a></h3><p>The panel layer a part belongs to. <code>0</code> is the frame, and the layers on each face are numbered outwards from it: <code>1</code>, <code>2</code> on one side and <code>-1</code>, <code>-2</code> on the other.</p><p>Most IFC files write that layer with a letter instead of a sign, usually <code>F</code> for the front face and <code>B</code> for the back one. produuz.it reads the letter: a value holding a <strong><code>B</code></strong> becomes a negative zone, and anything else stays positive.</p><table><thead><tr><th>IFC value</th><th>Detected zone</th></tr></thead><tbody><tr><td><code>F1</code></td><td>1</td></tr><tr><td><code>F2</code></td><td>2</td></tr><tr><td><code>B1</code></td><td>-1</td></tr><tr><td><code>B2</code></td><td>-2</td></tr><tr><td><code>Back2</code></td><td>-2</td></tr><tr><td><code>1</code></td><td>1</td></tr><tr><td><code>-1</code></td><td>-1</td></tr></tbody></table><p>Letters and other characters are stripped, so only the <code>B</code> changes the result. A value that already carries a minus sign is used as it is.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The <code>B</code> rule applies to every <strong>numeric</strong> property, not only the zone. Keep a <code>B</code> out of the values you map to <em>Nail/Screw CTC</em>, <em>Mill/Saw depth</em>, <em>Isolation order number</em> and <em>Tool ID</em>, because it would turn them negative.</p></div><h4 id="positive-side-zones" tabindex="-1">Positive side zones <a class="header-anchor" href="#positive-side-zones" aria-label="Permalink to &quot;Positive side zones {#positive-side-zones}&quot;">​</a></h4><h4 id="negative-side-zones" tabindex="-1">Negative side zones <a class="header-anchor" href="#negative-side-zones" aria-label="Permalink to &quot;Negative side zones {#negative-side-zones}&quot;">​</a></h4><p><strong>BTLx only.</strong> BTLx layer numbers come as plain numbers with no sign, so these two rule lists declare which layers belong to each face of the panel.</p><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3><h4 id="finish" tabindex="-1">Finish <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;Finish {#finish}&quot;">​</a></h4><p>The finish of the part.</p><h4 id="comment" tabindex="-1">Comment <a class="header-anchor" href="#comment" aria-label="Permalink to &quot;Comment {#comment}&quot;">​</a></h4><p>A free comment shown with the part.</p><h4 id="weight-kg" tabindex="-1">Weight (kg) <a class="header-anchor" href="#weight-kg" aria-label="Permalink to &quot;Weight (kg) {#weight-kg}&quot;">​</a></h4><p>The weight of the part in kg. Some exporters write it in the element property sets (<code>Weight</code>, <code>GEWICHT</code>), others export only the volume.</p><h4 id="volume-m3" tabindex="-1">Volume (m3) <a class="header-anchor" href="#volume-m3" aria-label="Permalink to &quot;Volume (m3) {#volume-m3}&quot;">​</a></h4><p>The volume of the part in m³. Exported by nearly every application, and what a weight can be derived from when the exporter writes none.</p><h4 id="isolation-order-number" tabindex="-1">Isolation order number <a class="header-anchor" href="#isolation-order-number" aria-label="Permalink to &quot;Isolation order number {#isolation-order-number}&quot;">​</a></h4><p>The order in which insulation areas are filled.</p><h2 id="custom-part-classes" tabindex="-1">Custom part classes <a class="header-anchor" href="#custom-part-classes" aria-label="Permalink to &quot;Custom part classes {#custom-part-classes}&quot;">​</a></h2><p>A <strong>category</strong> says what a part is: a stud, a rail, a plate. A <strong>class</strong> says how your factory treats it. They are two different questions, and a part answers both at once.</p><p>Classes are entirely your own. Nothing is built in and nothing is detected automatically: a part is an I-beam only because a rule you wrote says so.</p><p>Give each class a name and add the rules that recognise it, with the same kind of rule as the categories. A part gets the <strong>first class in the list whose rules match</strong>, so put the more specific classes first. A part that matches no class simply has none, and that is normal.</p><p>A class does two things.</p><p><strong>Its name</strong> is what other settings look up when they behave differently per kind of part — the framing nail matrix of the machine setups first of all. See: <a href="/guide/machine_files/machines/mobi_one/">Mobi One</a></p><p><strong>Its behaviours</strong> say what the class does to the panel measurements. That is the <em>Behaviours</em> button on each class.</p><h3 id="class-behaviours" tabindex="-1">Behaviours <a class="header-anchor" href="#class-behaviours" aria-label="Permalink to &quot;Behaviours {#class-behaviours}&quot;">​</a></h3><p>Every panel carries four measurements: its width, its height, its thickness and its surface. By default every part counts in all four. A behaviour takes the parts of one class out of one of them — or out of produuz.it altogether.</p><p><strong>Whole part</strong></p><table><thead><tr><th>Behaviour</th><th>What it does</th></tr></thead><tbody><tr><td>Ignore this part completely</td><td>The part never reaches the parts list, the reports or the machine files. Use it for helper geometry, annotations and anything the modeller exported by accident.</td></tr><tr><td>Hide in the 3D viewer</td><td>The part is still measured and still produced, it is only not drawn. Use it for insulation, foils and fillers that would cover the frame.</td></tr></tbody></table><p><strong>Measurements</strong></p><table><thead><tr><th>Behaviour</th><th>What it leaves the part out of</th></tr></thead><tbody><tr><td>Ignore in surface</td><td>The net area, the gross area and the opening areas of the panel</td></tr><tr><td>Ignore in width (X)</td><td>The width of the panel</td></tr><tr><td>Ignore in height (Y)</td><td>The height of the panel</td></tr><tr><td>Ignore in thickness (Z)</td><td>The thickness of the panel</td></tr></tbody></table><p>They are all <strong>off by default, and off means the part counts</strong> — which is what every part did before behaviours existed. Turning none on changes nothing.</p><div class="info custom-block"><p class="custom-block-title">The measurements are not only a report figure</p><p>The <strong>rack loads</strong> are drawn from them. The width decides how many panels fit in a rack row and the thickness how deep the stack builds, so a panel measured short is a rack plan that does not fit on the floor. See: <a href="/guide/logistics/delivery/">Delivery &amp; Racks</a></p></div><p>The four are separate because the measurements are separate, and that is what makes the useful cases possible.</p><div class="info custom-block"><p class="custom-block-title">Placeholder layers</p><p>The case behaviours were built for. Some modellers add a layer to a panel that is not produced but occupies the space a real one will take — an insulation layer, a finish, a service cavity.</p><p>That layer has to count for the <strong>thickness</strong>, because the panel really is that thick. It must not count for the <strong>surface</strong>, because nothing was produced.</p><p>Give it a class, turn on <em>Ignore in surface</em>, <em>Ignore in width</em> and <em>Ignore in height</em>, and leave <em>Ignore in thickness</em> <strong>off</strong>. The panel keeps its real thickness and its surface stops counting a layer nobody built.</p></div><div class="info custom-block"><p class="custom-block-title">A part that sticks out</p><p>A bracket or an anchor that reaches past the edge of the panel makes it read wider than it is. Give it a class and turn on <em>Ignore in width</em>, and only that one. It still counts everywhere else.</p></div><p>The class row shows what it ignores without opening anything, so a setup is readable at a glance.</p><div class="info custom-block"><p class="custom-block-title">When the numbers change</p><p>Panel measurements are worked out during the <strong>analysis</strong> of a design, not when you look at them. Saving the setup relaunches the analysis of the projects that use it, and the new numbers appear when it finishes.</p><p>If your company has <em>Launch analysis automatically</em> turned off in the company settings, nothing is relaunched and the old numbers stay until you launch the analysis yourself.</p></div><h2 id="operations-and-machines" tabindex="-1">Operations and machines <a class="header-anchor" href="#operations-and-machines" aria-label="Permalink to &quot;Operations and machines&quot;">​</a></h2><p>Nail lines, saw cuts, drills and glue are modelled as elements too. These rules tell them apart from parts, and the properties below feed the machine files directly.</p><div class="info custom-block"><p class="custom-block-title">They are never measured</p><p>An operation says what a machine does, not what the panel is made of, so nothing here counts towards the width, height, thickness or surface of a panel. A saw mark that hangs below the bottom rail does not make the panel taller.</p></div><h3 id="operation-lines" tabindex="-1">Operation lines <a class="header-anchor" href="#operation-lines" aria-label="Permalink to &quot;Operation lines&quot;">​</a></h3><h4 id="frame-nail-lines" tabindex="-1">Frame Nail Lines <a class="header-anchor" href="#frame-nail-lines" aria-label="Permalink to &quot;Frame Nail Lines {#frame-nail-lines}&quot;">​</a></h4><p>A group of frame nails represented as a line. The line goes through the heads of the nails.</p><h4 id="frame-nail-singles" tabindex="-1">Frame Nail Singles <a class="header-anchor" href="#frame-nail-singles" aria-label="Permalink to &quot;Frame Nail Singles {#frame-nail-singles}&quot;">​</a></h4><p>A single frame nail represented as a line. The line goes through the body of the nail.</p><h4 id="plate-nail-lines" tabindex="-1">Plate Nail Lines <a class="header-anchor" href="#plate-nail-lines" aria-label="Permalink to &quot;Plate Nail Lines {#plate-nail-lines}&quot;">​</a></h4><p>The same as frame nail lines, for nails into the plates.</p><h4 id="plate-screw" tabindex="-1">Plate Screw <a class="header-anchor" href="#plate-screw" aria-label="Permalink to &quot;Plate Screw {#plate-screw}&quot;">​</a></h4><p>Lines representing screws, read like the nail lines.</p><h4 id="glue-lines" tabindex="-1">Glue lines <a class="header-anchor" href="#glue-lines" aria-label="Permalink to &quot;Glue lines {#glue-lines}&quot;">​</a></h4><p>Glue lines, used for bricks.</p><h4 id="glue-areas" tabindex="-1">Glue areas <a class="header-anchor" href="#glue-areas" aria-label="Permalink to &quot;Glue areas {#glue-areas}&quot;">​</a></h4><p>Areas to be covered with glue.</p><h3 id="cutting-and-milling" tabindex="-1">Cutting and milling <a class="header-anchor" href="#cutting-and-milling" aria-label="Permalink to &quot;Cutting and milling&quot;">​</a></h3><h4 id="frame-saw" tabindex="-1">Frame Saw <a class="header-anchor" href="#frame-saw" aria-label="Permalink to &quot;Frame Saw {#frame-saw}&quot;">​</a></h4><p>Saw cuts on the frame.</p><h4 id="frame-drill" tabindex="-1">Frame Drill <a class="header-anchor" href="#frame-drill" aria-label="Permalink to &quot;Frame Drill {#frame-drill}&quot;">​</a></h4><p>Drills on the frame.</p><h4 id="milling" tabindex="-1">Milling <a class="header-anchor" href="#milling" aria-label="Permalink to &quot;Milling {#milling}&quot;">​</a></h4><p>Milling lines.</p><h4 id="sawing" tabindex="-1">Sawing <a class="header-anchor" href="#sawing" aria-label="Permalink to &quot;Sawing {#sawing}&quot;">​</a></h4><p>Sawing lines on the plates.</p><h4 id="drilling" tabindex="-1">Drilling <a class="header-anchor" href="#drilling" aria-label="Permalink to &quot;Drilling {#drilling}&quot;">​</a></h4><p>Drilling operations.</p><h3 id="machine-parameters" tabindex="-1">Machine parameters <a class="header-anchor" href="#machine-parameters" aria-label="Permalink to &quot;Machine parameters&quot;">​</a></h3><h4 id="nailscrew-ctc" tabindex="-1">Nail/Screw CTC <a class="header-anchor" href="#nailscrew-ctc" aria-label="Permalink to &quot;Nail/Screw CTC {#nailscrew-ctc}&quot;">​</a></h4><p>The centre-to-centre distance in nail and screw lines.</p><h4 id="millsaw-depth" tabindex="-1">Mill/Saw depth <a class="header-anchor" href="#millsaw-depth" aria-label="Permalink to &quot;Mill/Saw depth {#millsaw-depth}&quot;">​</a></h4><p>The depth of a milling or sawing line.</p><h4 id="tool-id-for-mob2-nailing" tabindex="-1">Tool ID for mob2 nailing <a class="header-anchor" href="#tool-id-for-mob2-nailing" aria-label="Permalink to &quot;Tool ID for mob2 nailing {#tool-id-for-mob2-nailing}&quot;">​</a></h4><p>The tool the MOB2 machine must use for the nailing.</p><h4 id="frame-saw-size" tabindex="-1">Frame Saw Size <a class="header-anchor" href="#frame-saw-size" aria-label="Permalink to &quot;Frame Saw Size {#frame-saw-size}&quot;">​</a></h4><p>The side of the frame the saw works on.</p><h4 id="brick-type" tabindex="-1">Brick Type <a class="header-anchor" href="#brick-type" aria-label="Permalink to &quot;Brick Type {#brick-type}&quot;">​</a></h4><p>The type of the brick.</p><h3 id="machine-flags" tabindex="-1">Machine flags <a class="header-anchor" href="#machine-flags" aria-label="Permalink to &quot;Machine flags&quot;">​</a></h3><p>Each of these has an IFC property and, beside it, a BTLx rule list that does the same job for BTLx files.</p><h4 id="bricks-machine-flag" tabindex="-1">Bricks: Machine Flag <a class="header-anchor" href="#bricks-machine-flag" aria-label="Permalink to &quot;Bricks: Machine Flag {#bricks-machine-flag}&quot;">​</a></h4><h4 id="bricks-machine-flag-btlx" tabindex="-1">Bricks: Machine Flag (BTLx) <a class="header-anchor" href="#bricks-machine-flag-btlx" aria-label="Permalink to &quot;Bricks: Machine Flag (BTLx) {#bricks-machine-flag-btlx}&quot;">​</a></h4><p>A brick that is machine built rather than laid by hand.</p><h4 id="isolation-machine-flag" tabindex="-1">Isolation: Machine Flag <a class="header-anchor" href="#isolation-machine-flag" aria-label="Permalink to &quot;Isolation: Machine Flag {#isolation-machine-flag}&quot;">​</a></h4><h4 id="isolation-machine-flag-btlx" tabindex="-1">Isolation: Machine Flag (BTLx) <a class="header-anchor" href="#isolation-machine-flag-btlx" aria-label="Permalink to &quot;Isolation: Machine Flag (BTLx) {#isolation-machine-flag-btlx}&quot;">​</a></h4><p>Insulation applied by the machine.</p><h4 id="battens-machine-flag" tabindex="-1">Battens: Machine Flag <a class="header-anchor" href="#battens-machine-flag" aria-label="Permalink to &quot;Battens: Machine Flag {#battens-machine-flag}&quot;">​</a></h4><h4 id="battens-machine-flag-btlx" tabindex="-1">Battens: Machine Flag (BTLx) <a class="header-anchor" href="#battens-machine-flag-btlx" aria-label="Permalink to &quot;Battens: Machine Flag (BTLx) {#battens-machine-flag-btlx}&quot;">​</a></h4><p>Battens fitted by the machine.</p><h4 id="milling-v-mill" tabindex="-1">Milling: V-Mill <a class="header-anchor" href="#milling-v-mill" aria-label="Permalink to &quot;Milling: V-Mill {#milling-v-mill}&quot;">​</a></h4><h4 id="milling-v-mill-btlx" tabindex="-1">Milling: V-Mill (BTLx) <a class="header-anchor" href="#milling-v-mill-btlx" aria-label="Permalink to &quot;Milling: V-Mill (BTLx) {#milling-v-mill-btlx}&quot;">​</a></h4><p>A milling line that must be done as a V-mill.</p><div class="info custom-block"><p class="custom-block-title">Skip Framing Wood is on the other tab</p><p>It follows the same pattern — one IFC property and one BTLx rule list beside it — but it sits with the areas and flags, on <a href="#skip-framing-wood">Panel part categories</a>.</p></div><h2 id="btlx-files" tabindex="-1">BTLx files <a class="header-anchor" href="#btlx-files" aria-label="Permalink to &quot;BTLx files&quot;">​</a></h2><p>BTLx files are read with the same setup, with two differences:</p><ul><li><strong>No property sets.</strong> BTLx parts carry plain attributes, so the <em>Read from a specific property set</em> checkbox is not offered on the BTLx rules, and a rule that names a property set never matches a BTLx part.</li><li><strong>Zones need declaring.</strong> BTLx layer numbers have no sign, so the face of the panel comes from the <a href="#positive-side-zones">Positive side zones</a> and <a href="#negative-side-zones">Negative side zones</a> rules instead of from a letter.</li></ul><p>The settings that are BTLx-only are marked with a <strong>BTLx</strong> chip in the editor.</p><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><p>The setup is validated before it is saved. If something is missing — a rule with an empty value, typically — you get a message and the editor opens the tab holding the offending field and scrolls to it.</p><div class="warning custom-block"><p class="custom-block-title">Saving relaunches the analysis</p><p>Saving a setup used by projects relaunches their analysis, so the parts are re-read with the new rules. The editor warns you before it does.</p></div><h2 id="moving-a-setup-around" tabindex="-1">Moving a setup around <a class="header-anchor" href="#moving-a-setup-around" aria-label="Permalink to &quot;Moving a setup around&quot;">​</a></h2><p>The <strong>↓</strong> button on a setup row downloads it as a JSON file, and <strong>UPLOAD</strong> in the toolbar reads one back in. That is how you copy a setup between companies, keep a version outside the platform, or have Claude write one for you.</p><p>Uploading saves nothing on its own: the file opens in this same editor, and it exists when you press Save.</p><p>See: <a href="/guide/management/ifcps/json/">The setup file (JSON)</a></p>',233),i=[s];function n(l,h,d,c,p,m){return a(),t("div",null,i)}const b=e(r,[["render",n]]);export{f as __pageData,b as default};
